import{_t as e,it as t,n,rt as r}from"./chunks/framework.BhEEDjPG.js";var i=JSON.parse(`{"title":"Security policy","description":"","frontmatter":{},"headers":[],"relativePath":"community/security-policy.md","filePath":"community/security-policy.md"}`),a={name:`community/security-policy.md`};function o(n,i,a,o,s,c){return e(),r(`div`,null,[...i[0]||=[t(`<h1 id="security-policy" tabindex="-1">Security policy <a class="header-anchor" href="#security-policy" aria-label="Permalink to “Security policy”">​</a></h1><h2 id="reporting-a-vulnerability" tabindex="-1">Reporting a vulnerability <a class="header-anchor" href="#reporting-a-vulnerability" aria-label="Permalink to “Reporting a vulnerability”">​</a></h2><p>Please report security problems privately to the maintainers (open a GitHub security advisory on this repository, or email the address in the repository profile). Do not open a public issue. We aim to acknowledge within 3 working days and to ship a fix or a mitigation before any public disclosure.</p><h2 id="scope" tabindex="-1">Scope <a class="header-anchor" href="#scope" aria-label="Permalink to “Scope”">​</a></h2><p>The gateway, the core runtime, the Verdict package, the widget, the example domain, and the deploy files in this repository. Your own domains, backends and model providers are yours.</p><h2 id="what-we-consider-in-scope" tabindex="-1">What we consider in scope <a class="header-anchor" href="#what-we-consider-in-scope" aria-label="Permalink to “What we consider in scope”">​</a></h2><ul><li>Reading or acting on another user&#39;s session (owner checks, identity verification).</li><li>Any path by which a model-emitted value reaches a client as HTML or an unlisted URL scheme.</li><li>Any write that bypasses the confirm gate.</li><li>Secrets or private user text reaching logs, spans or ledgers.</li><li>Denial of service through the rate-limit or cap paths.</li></ul><p>See <code>docs/SECURITY.md</code> for the design and <code>docs/PRODUCTION-CHECKLIST.md</code> for the deploy gate.</p><hr><p><small>Source: <a href="https://github.com/marg-adk/marg/blob/main/SECURITY.md">SECURITY.md</a> — edit it there; the site mirrors the repository.</small></p>`,10)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};